80 TOAST NOTIFICATION FLOATING PRO\n   ========================================================================== */\n.toast-notification {\n  position: fixed !important;\n  top: 25px !important;\n  right: 25px !important;\n  z-index: 12000 !important;\n  min-width: 320px;\n  max-width: 480px;\n  padding: 16px 20px;\n  border-radius: 8px;\n  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);\n  animation: slideInFromRight 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);\n}\n\n/* Th\u00E8me d'insertion accept\u00E9e (Vert) */\n.toast-notification.success {\n  background-color: #ecfdf5 !important;\n  border-left: 5px solid #059669 !important;\n  color: #065f46 !important;\n}\n\n/* Th\u00E8me d'erreur (Rouge) */\n.toast-notification.error {\n  background-color: #fef2f2 !important;\n  border-left: 5px solid #dc2626 !important;\n  color: #991b1b !important;\n}\n\n.toast-content {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.toast-icon {\n  font-size: 22px;\n  display: flex;\n  align-items: center;\n}\n\n.toast-message {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 1.5;\n  text-align: left;\n}\n\n/* Animation d'apparition dynamique */\n@keyframes slideInFromRight {\n  from { transform: translateX(130%); opacity: 0; }\n  to { transform: translateX(0); opacity: 1; }\n}\n\n/* Quiz optionnel + popup */\n.quiz-optional-card {\n  margin-top: 18px;\n  padding: 18px;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: linear-gradient(145deg, #faf5ff 0%, #f8fafc 100%);\n}\n\n.quiz-optional-header h4 {\n  margin: 0 0 4px;\n  font-size: 15px;\n  font-weight: 700;\n  color: #0f172a;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.quiz-optional-header h4 i {\n  color: #7c3aed;\n}\n\n.quiz-optional-header p {\n  margin: 0;\n  font-size: 12.5px;\n  color: #64748b;\n}\n\n.btn-activate-quiz {\n  margin-top: 14px;\n  width: 100%;\n  padding: 12px 16px;\n  border: 2px dashed #c4b5fd;\n  background: #fff;\n  color: #6b21a8;\n  font-s